const body = $input.item.json.body || {};
const newActivities = body.record?.data?.activity || [];
const oldActivities = body.old_record?.data?.activity || [];

// Create a set of previous IDs
const oldIds = new Set(oldActivities.map(a => a.id));

// Find newly added items
const addedActivities = newActivities.filter(a => a && a.id && !oldIds.has(a.id));

// Exclude silent tracking entries
const visibleActivities = addedActivities.filter(a => a.type !== 'share_copied');

if (visibleActivities.length === 0) {
  return [];
}

const formatActivity = (act) => {
  const name = act.name || act.userName || 'Someone';

  switch (act.type) {
    case 'checkin':
      return `🟢 *Check-in*: ${name} checked in.`;
    case 'checkout':
      return `🔴 *Check-out*: ${name} checked out.`;
    case 'leave':
      return `🌴 *Leave*: ${name} applied for leave (${act.text || 'Scheduled'}).`;
    case 'register':
      return `👤 *New User*: ${name} joined.`;
    case 'exit':
      return `🚪 *Exit*: ${name} logged out.`;
    case 'announcement':
      return `📢 *Notice Board Announcement*:\n${act.text || act.message || ''}`;
    case 'task_created':
      return `📋 *New Task*: "${act.text || act.title || 'Untitled'}" created by ${name}.`;
    case 'project_created':
      return `📁 *New Project*: "${act.text || act.title || 'Untitled'}" created.`;
    case 'due_changed':
      return `⏰ *Due Date Updated*: ${act.text || 'Task due date modified.'}`;
    default:
      return `📌 *Notice Board Update*:\n${act.text || `${name} performed ${act.type}`}`;
  }
};

return visibleActivities.map(act => ({
  json: {
    activity_id: act.id,
    activity_type: act.type,
    message: formatActivity(act)
  }
}));

